      --muted: #64748b;
      --border: rgba(148, 163, 184, 0.28);
      --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
      --accent: #2563eb;
      --accent-strong: #1d4ed8;
      --danger: #d92d20;
      --danger-strong: #b42318;
      --danger-soft: #fff3f2;
      --focus: #0f62fe;
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 14px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.12), transparent 28%),
        radial-gradient(circle at top right, rgba(14, 165, 233, 0.16), transparent 24%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--panel-solid);
      color: var(--text);
      font-weight: 700;
      text-decoration: none;
      transform: translateY(-160%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page-shell {
      width: min(1120px, calc(100% - 2rem));
      margin: 0 auto;
      padding: 2rem 0 4rem;
    }

    .hero {
      display: grid;
      gap: 1rem;
      margin-bottom: 2rem;
    }

    .eyebrow {
      margin: 0;
      color: var(--accent);
      font-size: 0.9rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.2rem, 4vw, 3.75rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 0;
      max-width: 44rem;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .layout {
      display: grid;
      gap: 1.5rem;
      grid-template-columns: minmax(0, 1.6fr) minmax(280px, 0.9fr);
      align-items: start;
    }

    .card,
    .aside-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-xl);
      background: var(--panel);
      backdrop-filter: blur(20px);
      box-shadow: var(--shadow);
    }

    .card {
      padding: 1.25rem;
    }

    .preview-frame {
      overflow: hidden;
      border-radius: calc(var(--radius-xl) - 8px);
      background: #dbe7f4;
      aspect-ratio: 4 / 3;
      margin-bottom: 1rem;
      border: 1px solid rgba(255, 255, 255, 0.65);
    }

    .preview-frame img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .card-footer {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
    }

    .meta h2 {
      margin: 0 0 0.35rem;
      font-size: 1.35rem;
      line-height: 1.2;
    }

    .meta p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .pill-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      margin-top: 1rem;
    }

    .pill {
      padding: 0.5rem 0.8rem;
      border-radius: 999px;
      background: rgba(37, 99, 235, 0.08);
      color: #1e3a8a;
      font-size: 0.92rem;
      font-weight: 600;
    }

    .button-row {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
      justify-content: flex-end;
    }

    button {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.9rem 1.2rem;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    button:focus-visible,
    .skip-link:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .button-secondary {
      background: var(--panel-solid);
      border-color: rgba(148, 163, 184, 0.4);
      color: var(--text);
    }

    .trigger,
    .button-danger {
      background: var(--danger);
      color: #ffffff;
      box-shadow: 0 10px 24px rgba(217, 45, 32, 0.25);
    }

    .trigger:hover,
    .button-danger:hover {
      background: var(--danger-strong);
    }

    .aside-card {
      padding: 1.4rem;
      display: grid;
      gap: 1rem;
    }

    .aside-card h2 {
      margin: 0;
      font-size: 1.1rem;
    }

    .aside-card p,
    .aside-card li {
      color: var(--muted);
      line-height: 1.6;
    }

    .aside-card ul {
      margin: 0;
      padding-left: 1.2rem;
    }

    .status {
      min-height: 1.5rem;
      color: #166534;
      font-weight: 700;
    }

    .status:empty {
      display: none;
    }

    .empty-state {
      display: none;
      padding: 3rem 1.5rem;
      text-align: center;
      border: 1px dashed rgba(148, 163, 184, 0.6);
      border-radius: calc(var(--radius-xl) - 8px);
      background: rgba(255, 255, 255, 0.58);
    }

    .empty-state h2 {
      margin: 0 0 0.75rem;
      font-size: 1.4rem;
    }

    .empty-state p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    dialog {
      width: min(92vw, 28rem);
      padding: 0;
      border: none;
      border-radius: 1.5rem;
      background: var(--panel-solid);
      color: var(--text);
      box-shadow: 0 30px 80px rgba(15, 23, 42, 0.35);
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.58);
      backdrop-filter: blur(4px);
    }

    .dialog-content {
      padding: 1.6rem;
    }

    .dialog-icon {
      display: inline-grid;
      place-items: center;
      width: 3rem;
      height: 3rem;
      margin-bottom: 1rem;
      border-radius: 999px;
      background: var(--danger-soft);
      color: var(--danger);
      font-size: 1.35rem;
      font-weight: 800;
    }

    dialog h2 {
      margin: 0 0 0.65rem;
      font-size: 1.45rem;
      line-height: 1.2;
    }

    dialog p {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
      margin-top: 1.5rem;
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 820px) {
      .layout {
        grid-template-columns: 1fr;
      }

      .card-footer,
      .button-row,
      .dialog-actions {
        justify-content: stretch;
      }

      .button-row button,
      .dialog-actions button {
        flex: 1 1 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      button,
      .card,
      .aside-card,
      dialog,
      .preview-frame,
      .empty-state {
        border: 1px solid CanvasText;
      }
    }
  </style>
</head>
