      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">This will remove <strong>Coastal Sunrise</strong> from your library. This action cannot be undone.</p>
      <form method="dialog" class="dialog-actions">
        <button type="submit" value="cancel" class="button-secondary">Cancel</button>
        <button type="submit" value="delete" class="button-danger">Delete image</button>
      </form>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById("delete-dialog");
    const trigger = document.querySelector(".trigger");
    const imageCard = document.getElementById("image-card");
    const emptyState = document.getElementById("empty-state");
    const statusMessage = document.getElementById("status-message");

    trigger.addEventListener("click", () => {
      dialog.showModal();
    });

    dialog.addEventListener("close", () => {
      if (dialog.returnValue !== "delete") {
        return;
      }

      imageCard.hidden = true;
      emptyState.style.display = "block";
      statusMessage.textContent = "Image deleted from your library.";
      emptyState.focus();
    });
  </script>
