    .aside-card p,
    .aside-card li {
      color: var(--muted);
      line-height: 1.6;
    }

    .aside-card ul {
      margin: 0;
      padding-left: 1.2rem;
    }

    .status {
      min-height: 1.5rem;
      color: #166534;
      font-weight: 700;
    }

    .status:empty {
      display: none;
    }

    .empty-state {
      display: none;
      padding: 3rem 1.5rem;
      text-align: center;
      border: 1px dashed rgba(148, 163, 184, 0.6);
      border-radius: calc(var(--radius-xl) - 8px);
      background: rgba(255, 255, 255, 0.58);
    }

    .empty-state h2 {
      margin: 0 0 0.75rem;
      font-size: 1.4rem;
    }

    .empty-state p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
