      border: none;
      border-radius: 1.5rem;
      background: var(--panel-solid);
      color: var(--text);
      box-shadow: 0 30px 80px rgba(15, 23, 42, 0.35);
    }

    dialog::backdrop {
      background: rgba(15, 23, 42, 0.58);
      backdrop-filter: blur(4px);
    }

    .dialog-content {
      padding: 1.6rem;
    }

    .dialog-icon {
      display: inline-grid;
      place-items: center;
      width: 3rem;
      height: 3rem;
      margin-bottom: 1rem;
      border-radius: 999px;
      background: var(--danger-soft);
      color: var(--danger);
      font-size: 1.35rem;
      font-weight: 800;
    }

    dialog h2 {
      margin: 0 0 0.65rem;
      font-size: 1.45rem;
      line-height: 1.2;
    }

    dialog p {
      margin: 0;
      color: var(--muted);
      line-height: 1.65;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      flex-wrap: wrap;
      margin-top: 1.5rem;
    }

    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
